def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, operators + - * / (integer division truncating toward zero).
    Returns integer result.
    """
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                # Python truncates toward negative infinity for //, need toward zero
                # Use int(a / b) which truncates toward zero.
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

