def solve(a, b):
    # Ensure that len(b) <= len(a) to use O(min) space
    if len(b) > len(a):
        a, b = b, a
    n, m = len(a), len(b)
    # previous row
    prev = list(range(m+1))
    for i in range(1, n+1):
        curr = [i] + [0]*m
        ai = a[i-1]
        for j in range(1, m+1):
            if ai == b[j-1]:
                curr[j] = prev[j-1]
            else:
                curr[j] = 1 + min(prev[j],      # deletion
                                   curr[j-1],   # insertion
