def solve(s):
    """Run-length encode an iterable of elements.
    Returns a list of [element, count] pairs.
    Handles empty input and non-iterable inputs gracefully.
    """
    # If s is falsy (e.g., None, empty string/list), return empty list.
    if not s:
        return []
    try:
        it = iter(s)
    except TypeError:
        # Non-iterable input, cannot encode.
        return []
    try:
        cur = next(it)
    except StopIteration:
        return []
    count = 1
    result = []
    for ch in it:
        if ch == cur:
            count += 1
        else:
            result.append([cur, count])
            cur = ch
            count = 1
    result.append([cur, count])
    return result

