    """Robust evaluation of Reverse Polish Notation.
    Accepts any iterable of tokens. Non‑numeric operands are ignored.
    If an operator lacks two operands, or division by zero occurs, returns 0.
    Division truncates toward zero.
    """
    # Guard against non‑iterable input
    try:
        it = iter(tokens)
    except Exception:
        return 0
    stack = []
    for tok in it:
        if isinstance(tok, str) and tok in {'+', '-', '*', '/'}:
            # Need two operands
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                # Division by zero check
                if b == 0:
                    return 0
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # Operand: try to convert to int
            try:
                stack.append(int(tok))
            except Exception:
                # Skip invalid operand
