def solve(a, b):
    # Handle None inputs gracefully.
    if a is None:
        a = ''
    if b is None:
        b = ''
    a = str(a)
    b = str(b)
    n, m = len(a), len(b)
    # Ensure the shorter string is b for O(min) space.
    if m > n:
        a, b = b, a
        n, m = m, n
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j],      # deletion
                                 cur[j - 1],   # insertion
                                 prev[j - 1])   # substitution
        prev = cur
    return prev[m]

