def solve(grid):
    """Count the number of islands (connected groups of 1s) in a 2D grid.
    Cells are connected orthogonally (up, down, left, right). The function
    gracefully handles None, empty inputs, and non‑list iterables.
    """
    # Guard against None or non‑iterable input
    if not grid:
        return 0
    try:
        rows = list(grid)
    except TypeError:
        return 0
    if not rows:
        return 0
    n = len(rows)
    m = len(rows[0]) if n > 0 else 0
    visited = [[False] * m for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n or y < 0 or y >= m:
                continue
            if visited[x][y] or rows[x][y] == 0:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    count = 0
    for i in range(n):
        for j in range(m):
            if rows[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    Handles empty list.
    """
    if not nums:
        return 0
    # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    import bisect
    tails = []
    for x in nums:
        # Find insertion point
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

