def solve(grid):
    """Count islands in a binary matrix.
    Accepts any iterable of iterables of 0/1 values. Returns 0 for falsy or
    malformed inputs. Uses BFS/DFS without modifying the input.
    """
    # Guard against non‑iterable or empty input
    try:
        rows = list(grid)
    except Exception:
        return 0
    if not rows:
        return 0
    # Ensure each row is a list for indexing; skip malformed rows
    matrix = []
    for r in rows:
        try:
            matrix.append(list(r))
        except Exception:
            continue
    if not matrix:
        return 0
    R, C = len(matrix), len(matrix[0])
    visited = [[False]*C for _ in range(R)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < R and 0 <= nj < C and not visited[ni][nj] and matrix[ni][nj]==1:
                    stack.append((ni,nj))
    count = 0
    for i in range(R):
        for j in range(C):
            if matrix[i][j]==1 and not visited[i][j]:
                count += 1
                dfs(i,j)
    return count

