    """Return elements of matrix in clockwise spiral order.
    Handles empty matrix, rows with varying lengths, and None entries gracefully.
    """
    if not matrix:
        return []
    # Determine maximum number of columns
    max_cols = max((len(row) for row in matrix), default=0)
    if max_cols == 0:
        return []
    rows = len(matrix)
    # Pad rows to rectangular shape with None
    rect = [row + [None] * (max_cols - len(row)) for row in matrix]
    top, bottom = 0, rows - 1
    left, right = 0, max_cols - 1
    res = []
    while top <= bottom and left <= right:
        # top row
        for j in range(left, right + 1):
            val = rect[top][j]
            if val is not None:
                res.append(val)
        top += 1
        # right column
        for i in range(top, bottom + 1):
            val = rect[i][right]
            if val is not None:
