        right -= 1
        if top <= bottom:
            # bottom row
            for j in range(right, left - 1, -1):
                val = rect[bottom][j]
                if val is not None:
                    res.append(val)
            bottom -= 1
        if left <= right:
            # left column
            for i in range(bottom, top - 1, -1):
                val = rect[i][left]
                if val is not None:
                    res.append(val)
            left += 1
    return res

