def solve(tokens):
    if not tokens: return 0
    stack=[]
    for tok in tokens:
        if isinstance(tok, (int, float)):
            stack.append(int(tok))
        else:
            if tok in '+-*/':
                b=stack.pop()
                a=stack.pop()
                if tok=='+': stack.append(a+b)
                elif tok=='-': stack.append(a-b)
                elif tok=='*': stack.append(a*b)
                else: stack.append(int(a/b))
            else:
                stack.append(int(tok))
    return stack[-1] if stack else 0

